   private JournalTransaction getTransactionInfo(final long txID) {
      JournalTransaction tx = transactions.get(txID);

      if (tx == null) {
         tx = new JournalTransaction(txID, this);

         JournalTransaction trans = transactions.putIfAbsent(txID, tx);

         if (trans != null) {
            tx = trans;
         }
      }

      return tx;
   }

